WITH kept_keys AS (SELECT channel FROM orders INTERSECT SELECT channel FROM orders WHERE shipping_fee < 35), kept_rows AS (SELECT s.* FROM orders s JOIN kept_keys k ON s.channel = k.channel) SELECT DATE_TRUNC('WEEK', order_date) AS week_start, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SUM(amount) FILTER (WHERE status = 'COMPLETED') AS completed_total_amount, AVG(shipping_fee) FILTER (WHERE channel = 'store') AS store_avg_shipping_fee, APPROX_PERCENTILE(discount, 0.95) AS discount_p95, SORT_ARRAY(COLLECT_SET(status)) AS status_list, CORR(discount, shipping_fee) AS corr_discount_shipping_fee FROM kept_rows GROUP BY week_start HAVING APPROX_PERCENTILE(discount, 0.95) >= 0
